import { useMemo, useState } from 'react';
import { Plus } from 'lucide-react';
import Header from './components/Header';
import BottomNav from './components/BottomNav';
import ProductDetail from './components/ProductDetail';
import ChatDetail from './components/ChatDetail';
import HomeFeed from './pages/HomeFeed';
import LifeFeed from './pages/LifeFeed';
import ChatList from './pages/ChatList';
import Profile from './pages/Profile';
import {
  initialMessages,
  initialRooms,
  productsSeed,
  type ChatRoom,
  type Message,
  type Product,
  type Tab,
} from './data/market';
import { roomFromProduct } from './utils/market';

export default function App() {
  const [tab, setTab] = useState<Tab>('home');
  const [products, setProducts] = useState<Product[]>(productsSeed);
  const [selected, setSelected] = useState<Product | null>(null);
  const [chatId, setChatId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('전체');
  const [rooms, setRooms] = useState<ChatRoom[]>(initialRooms);
  const [messages, setMessages] = useState<Record<string, Message[]>>(initialMessages);

  const unread = rooms.reduce((sum, room) => sum + room.unread, 0);
  const activeRoom = rooms.find((room) => room.id === chatId) || null;
  const visibleProducts = useMemo(() => {
    return products.filter((product) => {
      const q = query.trim().toLowerCase();
      const matchesQuery =
        !q ||
        product.title.toLowerCase().includes(q) ||
        product.location.toLowerCase().includes(q);
      const matchesFilter =
        filter === '전체' ||
        (filter === '나눔' && product.price === 0) ||
        product.category.includes(filter);
      return matchesQuery && matchesFilter;
    });
  }, [filter, products, query]);

  function toggleLike(id: string) {
    const update = (product: Product) => {
      if (product.id !== id) return product;
      const liked = !product.liked;
      return {
        ...product,
        liked,
        likes: Math.max(0, product.likes + (liked ? 1 : -1)),
      };
    };

    setProducts((current) => current.map(update));
    setSelected((current) => (current ? update(current) : current));
  }

  function openChat(product: Product) {
    const room = rooms.find((item) => item.productId === product.id);

    if (!room) {
      const next = roomFromProduct(product, '채팅이 시작되었습니다.', '방금', 0);
      setRooms((current) => [next, ...current]);
      setMessages((current) => ({
        ...current,
        [next.id]: [
          {
            id: 'start',
            system: true,
            text: '거래 전 물품 상태와 거래 장소를 꼭 확인해 주세요.',
            time: '방금',
          },
        ],
      }));
      setChatId(next.id);
    } else {
      setChatId(room.id);
      setRooms((current) =>
        current.map((item) => (item.id === room.id ? { ...item, unread: 0 } : item)),
      );
    }

    setSelected(null);
    setTab('chat');
  }

  function sendMessage(text: string) {
    if (!chatId || !text.trim()) return;
    const msg: Message = {
      id: Date.now().toString(),
      mine: true,
      text: text.trim(),
      time: new Date().toLocaleTimeString('ko-KR', {
        hour: '2-digit',
        minute: '2-digit',
      }),
    };

    setMessages((current) => ({ ...current, [chatId]: [...(current[chatId] || []), msg] }));
    setRooms((current) =>
      current.map((room) => (room.id === chatId ? { ...room, last: msg.text, time: '방금' } : room)),
    );
  }

  return (
    <div className="flex h-screen justify-center bg-neutral-100">
      <div className="relative h-screen w-full max-w-md overflow-hidden bg-white shadow-2xl">
        <Header tab={tab} unread={unread} />

        <main className="h-[calc(100vh-122px)] overflow-y-auto bg-white">
          {tab === 'home' && (
            <HomeFeed
              products={visibleProducts}
              query={query}
              filter={filter}
              setQuery={setQuery}
              setFilter={setFilter}
              onSelect={setSelected}
              onLike={toggleLike}
            />
          )}
          {tab === 'life' && <LifeFeed />}
          {tab === 'chat' && (
            <ChatList
              rooms={rooms}
              open={(id) => {
                setChatId(id);
                setRooms((current) =>
                  current.map((room) => (room.id === id ? { ...room, unread: 0 } : room)),
                );
              }}
            />
          )}
          {tab === 'me' && <Profile liked={products.filter((product) => product.liked).length} />}
        </main>

        {(tab === 'home' || tab === 'life') && (
          <button
            className="absolute bottom-[82px] right-4 z-30 flex h-12 items-center gap-1.5 rounded-full bg-[#ff6f0f] px-4 text-[15px] font-bold text-white shadow-[0_8px_24px_rgba(255,111,15,0.35)]"
            type="button"
          >
            <Plus size={20} />
            글쓰기
          </button>
        )}

        <BottomNav tab={tab} unread={unread} onChange={setTab} />

        {selected && (
          <ProductDetail
            product={selected}
            close={() => setSelected(null)}
            like={() => toggleLike(selected.id)}
            chat={() => openChat(selected)}
          />
        )}

        {activeRoom && (
          <ChatDetail
            room={activeRoom}
            messages={messages[activeRoom.id] || []}
            close={() => setChatId(null)}
            send={sendMessage}
          />
        )}
      </div>
    </div>
  );
}
